//go:build amd64

package fletcher4

import "golang.org/x/sys/cpu"

// sumAVX2 and sumAVX512 are generated by go-asmgen (internal/gen) into
// kernel_amd64.s. nblocks counts 32-byte (AVX2) or 64-byte (AVX-512) blocks of
// p; the lane accumulators are stored to out[g*L+j] (L = 4 or 8).
//
//go:noescape
func sumAVX2(p *byte, nblocks int, out *[32]uint64)

//go:noescape
func sumAVX512(p *byte, nblocks int, out *[32]uint64)

func allKernels() []kernel {
	return []kernel{
		{"avx2", 4, 32, sumAVX2, cpu.X86.HasAVX2},
		{"avx512", 8, 64, sumAVX512, cpu.X86.HasAVX512F},
	}
}
